CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_auth_session_user ON session("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "rateLimit" (id text PRIMARY KEY,key text UNIQUE,count integer,"lastRequest" bigint);
CREATE TABLE IF NOT EXISTS invitations (email text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,paid_enabled boolean NOT NULL DEFAULT false,wallet_micros bigint NOT NULL DEFAULT 0 CHECK(wallet_micros >= 0));
CREATE TABLE IF NOT EXISTS devices (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS devices_user ON devices(user_id);
CREATE TABLE IF NOT EXISTS device_requests (id text PRIMARY KEY,code_hash text NOT NULL UNIQUE,user_code_hash text NOT NULL UNIQUE,name text NOT NULL,user_id text REFERENCES "user"(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,last_polled_at timestamptz,attempts integer NOT NULL DEFAULT 0,consumed_at timestamptz);
CREATE TABLE IF NOT EXISTS usage_buckets (scope text NOT NULL,period text NOT NULL,spent_micros bigint NOT NULL DEFAULT 0 CHECK(spent_micros>=0),reserved_micros bigint NOT NULL DEFAULT 0 CHECK(reserved_micros>=0),PRIMARY KEY(scope,period));
CREATE TABLE IF NOT EXISTS model_catalog (id text PRIMARY KEY,config jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS reservations (id text PRIMARY KEY,user_id text REFERENCES "user"(id) ON DELETE SET NULL,request_key text NOT NULL UNIQUE,model text NOT NULL,source text NOT NULL CHECK(source IN ('free','paid')),max_cost_micros bigint NOT NULL CHECK(max_cost_micros>=0),reserved_charge_micros bigint NOT NULL DEFAULT 0,actual_cost_micros bigint,input_tokens bigint,output_tokens bigint,day text NOT NULL,month text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','settled','uncertain','released')),generation_id text,created_at timestamptz NOT NULL DEFAULT now(),settled_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_reservation ON reservations(user_id) WHERE status IN ('pending','uncertain');
CREATE TABLE IF NOT EXISTS wallet_ledger (id text PRIMARY KEY,user_id text REFERENCES "user"(id) ON DELETE SET NULL,reference text NOT NULL UNIQUE,amount_micros bigint NOT NULL,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_events (id text PRIMARY KEY,type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS checkouts (id text PRIMARY KEY,user_id text REFERENCES "user"(id) ON DELETE SET NULL,stripe_session_id text UNIQUE,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS request_limits (key text NOT NULL,bucket bigint NOT NULL,count integer NOT NULL,PRIMARY KEY(key,bucket));
